"""Source-gated CARLA construction for the six NRS 484B.257(2) cases.

The local operator supplies a reviewed site survey. Survey values select Native
objects; they never substitute for Native readback. No CARLA import occurs here.
"""
from __future__ import annotations

import hashlib
import json
from math import hypot, isfinite
from pathlib import Path


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _source(root, item):
    if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
        raise ValueError("original source reference is incomplete")
    name = item["path"]
    if not isinstance(name, str) or not name or Path(name).is_absolute() or Path(name).name != name:
        raise ValueError("original source must be a direct child of site bundle")
    path = root / name
    if not path.is_file() or _sha(path) != item["sha256"]:
        raise ValueError("original source missing or changed: " + name)
    return path


def _finite(value, name):
    if type(value) not in (int, float) or not isfinite(value):
        raise ValueError("nonfinite " + name)
    return float(value)


def _pose(value, name):
    if not isinstance(value, dict) or set(value) != {"x", "y", "z", "yaw"}:
        raise ValueError("source-surveyed transform missing: " + name)
    return {key: _finite(value[key], name + "." + key) for key in value}


def load_site(bundle, case_id, control_context):
    """Validate immutable survey inventory before connecting to CARLA."""
    root = Path(bundle).resolve()
    index = json.loads((root / "bundle-index.json").read_text())
    if (index.get("format") != "c158196-original-site-bundle" or
            index.get("cell_id") != "C158196" or
            index.get("case_id") != case_id or
            index.get("control_context") != control_context):
        raise ValueError("original site bundle does not match exact case")
    refs = index.get("sources")
    if not isinstance(refs, list) or len(refs) < 3:
        raise ValueError("original map/device/route sources missing")
    paths = {item.get("path") for item in refs if isinstance(item, dict)}
    if paths != {"site.json", "devices.json", "routes.json"}:
        raise ValueError("unexpected original site source inventory")
    docs = {item["path"]: json.loads(_source(root, item).read_text()) for item in refs}
    site, devices, routes = docs["site.json"], docs["devices.json"], docs["routes.json"]
    if (site.get("cell_id") != "C158196" or
            site.get("layout") != "one_way_to_two_way_intersection" or
            site.get("through_highway") is not False or
            not isinstance(site.get("native_map_name"), str) or
            not site["native_map_name"]):
        raise ValueError("reviewed site cannot establish non-through intersection")
    bounds = site.get("intersection_rectangle_xy")
    if (not isinstance(bounds, list) or len(bounds) != 4 or
            not all(type(x) in (int, float) and isfinite(x) for x in bounds) or
            not bounds[0] < bounds[2] or not bounds[1] < bounds[3]):
        raise ValueError("reviewed intersection bounds missing")
    views = {"overview", "approach", "reference_corner", "driver_reference"}
    poses = site.get("camera_poses")
    if not isinstance(poses, dict) or set(poses) != views:
        raise ValueError("four source-surveyed original camera poses required")
    for name, pose in poses.items():
        if not isinstance(pose, dict) or set(pose) != {"x", "y", "z", "pitch", "yaw", "roll", "fov_deg"}:
            raise ValueError("source-surveyed camera pose incomplete: " + name)
        for key, value in pose.items():
            _finite(value, name + "." + key)
        if not 30 <= pose["fov_deg"] <= 120:
            raise ValueError("source-surveyed camera FOV invalid: " + name)
    if (devices.get("case_id") != case_id or
            devices.get("control_context") != control_context or
            not isinstance(devices.get("ego_control_actor_id"), int) or
            devices.get("facing_road_id") != routes.get("ego_approach", {}).get("road_id") or
            devices.get("facing_lane_id") != routes.get("ego_approach", {}).get("lane_id") or
            not isinstance(devices.get("counterpart_priority_source"), dict)):
        raise ValueError("original controlling authority inventory missing")
    if control_context in {"stop_sign", "yield_sign"}:
        if (devices.get("sign_kind") != control_context or
                devices.get("signal_controlling") is not False or
                devices.get("officer_controlling") is not False):
            raise ValueError("sign branch lacks independent controlling sign")
    elif control_context == "signal_exception":
        if devices.get("signal_controlling") is not True:
            raise ValueError("signal exception source missing")
    elif control_context == "officer_exception":
        if devices.get("officer_controlling") is not True:
            raise ValueError("officer exception source missing")
    else:
        raise ValueError("unsupported control context")
    if (routes.get("case_id") != case_id or
            not isinstance(routes.get("ego_approach"), dict) or
            not isinstance(routes.get("counterpart_route"), dict)):
        raise ValueError("original route survey missing")
    for name in ("ego_approach", "counterpart_route"):
        route = routes[name]
        if (not isinstance(route.get("road_id"), int) or
                not isinstance(route.get("lane_id"), int) or
                not isinstance(route.get("native_waypoints"), list) or
                len(route["native_waypoints"]) < 2):
            raise ValueError("source-surveyed Native route missing: " + name)
        for point in route["native_waypoints"]:
            _pose(point, name)
    if (routes["ego_approach"]["road_id"], routes["ego_approach"]["lane_id"]) == (
            routes["counterpart_route"]["road_id"], routes["counterpart_route"]["lane_id"]):
        raise ValueError("counterpart has no distinct route")
    return {"root": root, "index": index, "site": site, "devices": devices,
            "routes": routes, "source_hashes": {x["path"]: x["sha256"] for x in refs}}


class NativeAdapter:
    """Read back surveyed Native entities before spawning either participant."""

    def __init__(self, world, carla, survey, case_spec):
        self.world, self.carla, self.survey = world, carla, survey
        self.case_spec = case_spec
        if (case_spec.get("case_id") != survey["index"]["case_id"] or
                case_spec.get("control_context") != survey["devices"]["control_context"] or
                case_spec.get("cell_id") != "C158196"):
            raise ValueError("Native adapter differs from selected exact case")
        self.actors = {}
        self.target_speeds = {}
        self.map_verified = False
        self.verified = False

    def _location(self, point):
        return self.carla.Location(x=point["x"], y=point["y"], z=point["z"])

    def _route(self, name):
        route = self.survey["routes"][name]
        native_map = self.world.get_map()
        for point in route["native_waypoints"]:
            pose = _pose(point, name)
            waypoint = native_map.get_waypoint(self._location(pose), project_to_road=False)
            if waypoint is None or (waypoint.road_id, waypoint.lane_id) != (
                    route["road_id"], route["lane_id"]):
                raise ValueError("Native map route does not match original survey: " + name)
            p = waypoint.transform.location
            if hypot(p.x - pose["x"], p.y - pose["y"]) > 1.5:
                raise ValueError("Native waypoint drift from original survey: " + name)
        return route

    def inspect_intersection(self):
        site = self.survey["site"]
        if self.world.get_map().name != site["native_map_name"]:
            raise ValueError("Native map differs from original site")
        self._route("ego_approach")
        self._route("counterpart_route")
        bounds = site["intersection_rectangle_xy"]
        midpoint = ((bounds[0] + bounds[2]) / 2, (bounds[1] + bounds[3]) / 2)
        counterpart = self.survey["routes"]["counterpart_route"]["native_waypoints"][0]
        measured_station = hypot(counterpart["x"] - midpoint[0], counterpart["y"] - midpoint[1])
        planned_station = _finite(self.case_spec.get("counterpart_start_m"), "counterpart start")
        if abs(measured_station - planned_station) > 1.5:
            raise ValueError("Native counterpart start differs from frozen engineering contrast")
        self.map_verified = True
        return {"layout": site["layout"], "through_highway": site["through_highway"],
                "intersection_rectangle_xy": site["intersection_rectangle_xy"],
                "source": "site.json:" + self.survey["source_hashes"]["site.json"]}

    def inspect_devices(self):
        if not self.map_verified:
            raise ValueError("Native map readback required before device inspection")
        devices = self.survey["devices"]
        actor = self.world.get_actor(devices["ego_control_actor_id"])
        if actor is None or actor.id != devices["ego_control_actor_id"]:
            raise ValueError("surveyed controlling actor absent from Native world")
        expected = {"stop_sign": "traffic.stop", "yield_sign": "traffic.yield",
                    "signal_exception": "traffic.traffic_light", "officer_exception": "walker."}
        context = devices["control_context"]
        if not actor.type_id.startswith(expected[context]):
            raise ValueError("Native controlling actor type differs from original survey")
        if context == "signal_exception":
            state = actor.get_state()
            actual = getattr(state, "name", str(state).split(".")[-1]).lower()
            if actual != devices.get("signal_state"):
                raise ValueError("Native signal state differs from original survey")
        if context == "officer_exception" and not devices.get("original_officer_control_log"):
            raise ValueError("original officer control observation missing")
        priority = devices["counterpart_priority_source"]
        if (priority.get("route_road_id") != self.survey["routes"]["counterpart_route"]["road_id"] or
                priority.get("unobligated") is not True or
                not priority.get("original_device_survey")):
            raise ValueError("counterpart priority not established by original source")
        self.verified = True
        return {"source": "devices.json:" + self.survey["source_hashes"]["devices.json"],
                "context": context,
                "signal_controlling": devices.get("signal_controlling"),
                "exception_active": context in {"signal_exception", "officer_exception"}}

    def spawn_vehicle(self, role, spawn):
        if not self.verified:
            raise ValueError("Native map and devices must be verified before spawn")
        name = {"ego": "ego_approach", "counterpart": "counterpart_route"}.get(role)
        if name is None or spawn.get("resolve_from_native_map") is not True:
            raise ValueError("unsupported vehicle role or unresolved Native spawn")
        route = self.survey["routes"][name]
        point = _pose(route["native_waypoints"][0], name)
        location = self._location(point)
        transform = self.carla.Transform(location, self.carla.Rotation(yaw=point["yaw"]))
        blueprint_id = route.get("vehicle_blueprint")
        if not isinstance(blueprint_id, str) or not blueprint_id.startswith("vehicle."):
            raise ValueError("original vehicle blueprint missing")
        blueprint = self.world.get_blueprint_library().find(blueprint_id)
        if blueprint is None:
            raise ValueError("surveyed vehicle blueprint absent")
        actor = self.world.try_spawn_actor(blueprint, transform)
        if actor is None:
            raise ValueError("Native vehicle spawn failed")
        self.actors[role] = actor
        return actor.id

    def set_target_speed(self, actor_id, speed):
        if actor_id not in {actor.id for actor in self.actors.values()}:
            raise ValueError("target speed assigned to unowned actor")
        target = _finite(speed, "target speed")
        if not 0 < target <= 15:
            raise ValueError("target speed outside engineering range")
        # Requested speeds are controller targets, not fabricated measurements.
        # A heading-aware controller must apply controls on each Native tick.
        self.target_speeds[actor_id] = target

    def step(self, controller):
        """Apply only controls computed from original Native actor state."""
        if set(self.target_speeds) != {actor.id for actor in self.actors.values()}:
            raise ValueError("both participant targets required")
        for role, actor in self.actors.items():
            command = controller(role, actor, self.target_speeds[actor.id],
                                 self.survey["routes"]["ego_approach" if role == "ego" else "counterpart_route"],
                                 self.survey["site"]["intersection_rectangle_xy"],
                                 self.survey["devices"])
            if not isinstance(command, dict) or set(command) != {"throttle", "brake", "steer"}:
                raise ValueError("controller failed to return three Native controls")
            for key, value in command.items():
                number = _finite(value, key)
                if not ((-1 <= number <= 1) if key == "steer" else (0 <= number <= 1)):
                    raise ValueError("controller returned out-of-range control")
            actor.apply_control(self.carla.VehicleControl(**command))

    def destroy(self):
        for actor in reversed(list(self.actors.values())):
            actor.destroy()
        self.actors.clear()
        self.target_speeds.clear()
        self.map_verified = False
        self.verified = False

"""Conservative engineering controller for the surveyed intersection.

The controller uses current Native observations only. A proximity hold is an
engineering safety choice and never labels a statutory immediate hazard.
"""
from __future__ import annotations

from math import atan2, cos, hypot, isfinite, pi, sin


def _number(value, name):
    if type(value) not in (int, float) or not isfinite(value):
        raise ValueError("missing Native " + name)
    return float(value)


def _inside(x, y, bounds):
    return bounds[0] <= x <= bounds[2] and bounds[1] <= y <= bounds[3]


class IntersectionController:
    """One policy instance per exact attempt, with explicit source readers."""

    def __init__(self, counterpart_reader, authority_reader, throttle_scale=1.0):
        if not callable(counterpart_reader) or not callable(authority_reader):
            raise ValueError("original counterpart and authority readers required")
        if type(throttle_scale) not in (int, float) or not .5 <= throttle_scale <= 1:
            raise ValueError("engineering throttle scale outside reviewed range")
        self.counterpart_reader = counterpart_reader
        self.authority_reader = authority_reader
        self.throttle_scale = float(throttle_scale)
        self.full_stop_observed = False

    def __call__(self, role, actor, target, route, bounds, devices):
        if role not in {"ego", "counterpart"}:
            raise ValueError("unknown Native participant")
        frame = self.authority_reader()
        if not isinstance(frame, dict) or type(frame.get("native_frame")) is not int:
            raise ValueError("original authority frame required")
        if frame.get("control_context") != devices.get("control_context"):
            raise ValueError("Native authority context changed")
        if frame.get("ego_control_actor_id") != devices.get("ego_control_actor_id"):
            raise ValueError("Native authority actor changed")
        transform = actor.get_transform()
        location, rotation = transform.location, transform.rotation
        x, y = _number(location.x, "x"), _number(location.y, "y")
        velocity = actor.get_velocity()
        speed = hypot(_number(velocity.x, "vx"), _number(velocity.y, "vy"))
        points = route.get("native_waypoints")
        if not isinstance(points, list) or len(points) < 2:
            raise ValueError("source-surveyed route missing")
        # Select the next waypoint strictly ahead of the nearest sampled station.
        nearest = min(range(len(points)), key=lambda i:
                      hypot(x - points[i]["x"], y - points[i]["y"]))
        aim = points[min(nearest + 1, len(points) - 1)]
        desired = atan2(aim["y"] - y, aim["x"] - x)
        heading = _number(rotation.yaw, "yaw") * pi / 180
        error = atan2(sin(desired - heading), cos(desired - heading))
        steer = max(-0.65, min(0.65, error / 1.2))
        if role == "counterpart":
            return {"throttle": 0.3 * self.throttle_scale if speed < target else 0.0,
                    "brake": 0.15 if speed > target + 0.6 else 0.0,
                    "steer": steer}
        context = devices["control_context"]
        if context == "signal_exception":
            if frame.get("signal_state") != devices.get("signal_state"):
                raise ValueError("Native controlling signal changed")
            go = frame.get("signal_permission") is True
        elif context == "officer_exception":
            if frame.get("officer_actor_visible") is not True:
                raise ValueError("original officer control observation missing")
            go = frame.get("officer_permission") is True
        elif context in {"stop_sign", "yield_sign"}:
            if frame.get("signal_controlling") is not False or frame.get("officer_controlling") is not False:
                raise ValueError("sign no longer independently controls")
            go = True
        else:
            raise ValueError("unsupported authority")
        counterpart = self.counterpart_reader()
        if (not isinstance(counterpart, dict) or
                counterpart.get("native_frame") != frame["native_frame"] or
                counterpart.get("unobligated") is not True):
            raise ValueError("same-frame original counterpart priority missing")
        ox, oy = _number(counterpart.get("x"), "counterpart x"), _number(counterpart.get("y"), "counterpart y")
        # Engineering hold distance protects test actors; it is not a legal
        # definition of an immediate hazard and is never emitted as one.
        occupied_or_close = _inside(ox, oy, bounds) or hypot(ox - x, oy - y) < 8
        before_entry = not _inside(x, y, bounds)
        entry_x = min(max(x, bounds[0]), bounds[2])
        entry_y = min(max(y, bounds[1]), bounds[3])
        distance_to_entry = hypot(x - entry_x, y - entry_y)
        if context == "stop_sign" and before_entry and distance_to_entry <= 5:
            if speed <= 0.05:
                self.full_stop_observed = True
            if not self.full_stop_observed:
                return {"throttle": 0.0, "brake": 0.75, "steer": steer}
        if not go or (before_entry and occupied_or_close):
            return {"throttle": 0.0, "brake": 0.7, "steer": steer}
        return {"throttle": 0.25 * self.throttle_scale if speed < target else 0.0,
                "brake": 0.12 if speed > target + 0.5 else 0.0,
                "steer": steer}

"""Original-frame measurements for NRS 484B.257(2) delivery review.

This module checks observable histories. It never assigns a legal hazard label.
"""
from __future__ import annotations

from math import hypot, isfinite

FPS = 20
FRAMES = 900


def build_case(adapter, spec):
    """Construct only after a native map/device readback supports the case.

    The adapter is injected, so importing this module never imports CARLA. The
    adapter must expose inspect_intersection, inspect_devices, spawn_vehicle,
    and set_target_speed. It must retain its source paths in the returned record.
    """
    if spec.get("cell_id") != "C158196" or spec.get("law_id") != "NRS-484B-257-2":
        raise ValueError("wrong frozen cell or law")
    if spec.get("control_context") not in {"stop_sign", "yield_sign", "signal_exception", "officer_exception"}:
        raise ValueError("invalid requested control")
    if spec.get("counterpart_start_m", 0) < 0 or spec.get("counterpart_start_m", 0) > 100:
        raise ValueError("counterpart start outside reviewed engineering range")
    road = adapter.inspect_intersection()
    if road.get("layout") != "one_way_to_two_way_intersection" or not road.get("through_highway") is False:
        raise ValueError("native road geometry does not support this branch")
    _rect(road.get("intersection_rectangle_xy"))
    if not road.get("source"):
        raise ValueError("native map source missing")
    devices = adapter.inspect_devices()
    if not devices.get("source") or devices.get("context") != spec["control_context"]:
        raise ValueError("native device context does not match requested case")
    if spec["control_context"] in {"stop_sign", "yield_sign"} and devices.get("signal_controlling") is not False:
        raise ValueError("controlling traffic light defeats sign branch")
    if spec["control_context"] in {"signal_exception", "officer_exception"} and devices.get("exception_active") is not True:
        raise ValueError("exception context not physically observed")
    ego = adapter.spawn_vehicle("ego", spec["ego_spawn"])
    other = adapter.spawn_vehicle("counterpart", spec["counterpart_spawn"])
    adapter.set_target_speed(ego, spec["ego_target_mps"])
    adapter.set_target_speed(other, spec["counterpart_target_mps"])
    return {"road_source": road["source"], "device_source": devices["source"],
            "ego_id": ego, "counterpart_id": other,
            "requested_targets_only": True}


def _point(value, name):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError(f"{name} requires two coordinates")
    if not all(isinstance(v, (int, float)) and isfinite(v) for v in value):
        raise ValueError(f"{name} has nonfinite coordinates")
    return tuple(float(v) for v in value)


def _inside(point, rectangle):
    x, y = _point(point, "body vertex")
    x0, y0, x1, y1 = rectangle
    return x0 <= x <= x1 and y0 <= y <= y1


def _body(sample, name):
    vertices = sample.get("body_vertices_xy")
    if not isinstance(vertices, list) or len(vertices) != 4:
        raise ValueError(f"{name} requires four original body vertices")
    return [_point(v, name) for v in vertices]


def _rect(value):
    if not isinstance(value, list) or len(value) != 4:
        raise ValueError("intersection rectangle requires four bounds")
    if not all(isinstance(v, (int, float)) and isfinite(v) for v in value):
        raise ValueError("intersection rectangle has nonfinite bounds")
    x0, y0, x1, y1 = map(float, value)
    if not x0 < x1 or not y0 < y1:
        raise ValueError("intersection rectangle is empty")
    return x0, y0, x1, y1


def _overlap(vertices, rect):
    # The delivered rectangle must also intersect a body containing a corner.
    x0, y0, x1, y1 = rect
    bx0 = min(v[0] for v in vertices)
    by0 = min(v[1] for v in vertices)
    bx1 = max(v[0] for v in vertices)
    by1 = max(v[1] for v in vertices)
    return bx0 <= x1 and bx1 >= x0 and by0 <= y1 and by1 >= y0


def measure(packet, expected_control, expected_relation="within"):
    """Require synchronized, source-backed Native records and return event brackets.

    `stop_sign` and `yield_sign` are measured device states, not case-name facts.
    A yielding maneuver is retained as speed and geometry; sufficiency remains a
    human legal judgment. A signal/officer case is an explicit exception context.
    """
    if expected_control not in {"stop_sign", "yield_sign", "signal_exception", "officer_exception"}:
        raise ValueError("unsupported control context")
    if expected_relation not in {"within", "approaching"}:
        raise ValueError("unsupported counterpart relation")
    sources = packet.get("sources")
    required = {"native_world", "native_devices", "native_ego", "native_counterpart", "camera_sync"}
    if not isinstance(sources, dict) or not required <= set(sources):
        raise ValueError("missing original source inventory")
    if any(not isinstance(sources[k], str) or not sources[k] for k in required):
        raise ValueError("empty original source reference")
    rect = _rect(packet.get("intersection_rectangle_xy"))
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) != FRAMES:
        raise ValueError("expected full 900-frame original history")
    first_native_frame = frames[0].get("native_frame")
    if type(first_native_frame) is not int or first_native_frame < 0:
        raise ValueError("original Native first frame missing")
    first_time_s = frames[0].get("time_s")
    if type(first_time_s) not in (int, float) or not isfinite(first_time_s):
        raise ValueError("original Native first time missing")
    ego_overlap = []
    other_inside = []
    other_center = []
    speeds = []
    distances = []
    for index, frame in enumerate(frames):
        if frame.get("native_frame") != first_native_frame + index:
            raise ValueError("missing or reordered original frame")
        time_s = frame.get("time_s")
        if not isinstance(time_s, (int, float)) or abs(time_s - first_time_s - index / FPS) > 0.001:
            raise ValueError("non-20Hz original elapsed time")
        if frame.get("camera_frame") != index:
            raise ValueError("camera and Native frame maps differ")
        if frame.get("control_context") != expected_control:
            raise ValueError("device/officer context changed within attempt")
        authority = frame.get("authority")
        if (not isinstance(authority, dict) or
                authority.get("native_frame") != first_native_frame + index or
                authority.get("control_context") != expected_control or
                type(authority.get("ego_control_actor_id")) is not int):
            raise ValueError("original same-frame controlling authority missing")
        if expected_control in {"stop_sign", "yield_sign"}:
            if authority.get("signal_controlling") is not False or authority.get("officer_controlling") is not False:
                raise ValueError("sign lost independent control")
        if expected_control == "signal_exception" and authority.get("signal_state") is None:
            raise ValueError("original controlling signal state missing")
        if expected_control == "officer_exception" and authority.get("officer_actor_visible") is not True:
            raise ValueError("original officer control observation missing")
        ego = frame.get("ego")
        other = frame.get("counterpart")
        if not isinstance(ego, dict) or not isinstance(other, dict):
            raise ValueError("missing vehicle state")
        ebody = _body(ego, "ego")
        obody = _body(other, "counterpart")
        speed = ego.get("speed_mps")
        if not isinstance(speed, (int, float)) or not isfinite(speed) or speed < 0:
            raise ValueError("missing measured ego speed")
        if not isinstance(ego.get("applied_controls"), dict):
            raise ValueError("missing applied ego controls")
        if other.get("obligated_to_stop_or_yield") is not False:
            raise ValueError("counterpart priority is unverified")
        ec = tuple(sum(v[j] for v in ebody) / 4 for j in (0, 1))
        oc = tuple(sum(v[j] for v in obody) / 4 for j in (0, 1))
        ego_overlap.append(_overlap(ebody, rect))
        other_inside.append(all(_inside(v, rect) for v in obody))
        other_center.append(oc)
        speeds.append(float(speed))
        distances.append(hypot(ec[0] - oc[0], ec[1] - oc[1]))
    occupied = [i for i, value in enumerate(ego_overlap) if value]
    if not occupied:
        raise ValueError("ego never reaches intersection")
    if occupied[0] == 0 or occupied[-1] == FRAMES - 1:
        raise ValueError("intersection entry/clearance brackets missing")
    if expected_relation == "within":
        if not any(other_inside[:occupied[-1] + 1]):
            raise ValueError("no counterpart fully within intersection during approach or crossing")
    else:
        entry = occupied[0]
        if entry < 2:
            raise ValueError("no counterpart approach history")
        x0, y0, x1, y1 = rect
        center = ((x0 + x1) / 2, (y0 + y1) / 2)
        station = [hypot(p[0] - center[0], p[1] - center[1]) for p in other_center]
        if other_inside[entry] or not station[entry] < station[entry - 2]:
            raise ValueError("counterpart approach not observed before ego entry")
    if expected_control == "stop_sign" and min(speeds[:occupied[0]]) > 0.05:
        raise ValueError("no observed stop before intersection")
    return {
        "entry_frame": occupied[0],
        "clearance_frame": occupied[-1] + 1,
        "counterpart_within_frames": [i for i in occupied if other_inside[i]],
        "counterpart_pre_entry_within_frames": [i for i in range(occupied[0])
                                                if other_inside[i]],
        "counterpart_relation_observed": expected_relation,
        "counterpart_center_station_at_entry_m": hypot(
            other_center[occupied[0]][0] - (rect[0] + rect[2]) / 2,
            other_center[occupied[0]][1] - (rect[1] + rect[3]) / 2),
        "crossing_mean_speed_mps": sum(speeds[i] for i in occupied) / len(occupied),
        "minimum_center_distance_m": min(distances[i] for i in occupied),
        "legal_hazard_judgment": "unresolved",
    }


def compare(left, right, fields):
    """Check exact fixed context and at least one declared physical difference."""
    if not fields:
        raise ValueError("comparison needs declared difference")
    for key in ("map_sha256", "intersection_rectangle_xy", "ego_blueprint", "counterpart_blueprint", "weather", "fps", "camera_policy"):
        if left.get(key) != right.get(key):
            raise ValueError(f"fixed condition changed: {key}")
    if left.get("fps") != FPS:
        raise ValueError("wrong frame rate")
    if not any(left.get(key) != right.get(key) for key in fields):
        raise ValueError("declared difference not realized")
    return True

"""CARLA-lazy four-view original camera recorder for signed-intersection attempts."""
from __future__ import annotations

import hashlib
import io
import subprocess
from pathlib import Path
from queue import Empty, Queue

from PIL import Image

VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
PRODUCTION_PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
                      "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class OriginalCameraRecorder:
    def __init__(self, sensors: dict, scratch: Path, *,
                 profile: dict = PRODUCTION_PROFILE, expected_frames: int = 900,
                 diagnostic_fixture: bool = False, timeout_s: float = 5.0):
        if set(sensors) != set(VIEWS) or set(profile) != set(VIEWS):
            raise ValueError('four original camera sensors and profile required')
        if profile != PRODUCTION_PROFILE and not diagnostic_fixture:
            raise ValueError('profile override requires diagnostic fixture')
        if expected_frames < 2 or timeout_s <= 0:
            raise ValueError('valid original frame count and timeout required')
        self.sensors = sensors
        self.profile = profile
        self.expected_frames = expected_frames
        self.timeout_s = timeout_s
        self.scratch = Path(scratch)
        if not self.scratch.is_dir() or any((self.scratch / view).exists() for view in VIEWS):
            raise ValueError('fresh camera scratch directory required')
        self.queues = {view: Queue(maxsize=expected_frames + 2) for view in VIEWS}
        self.count = 0
        self.closed = False
        for view in VIEWS:
            (self.scratch / view).mkdir()
            sensors[view].listen(lambda image, view=view: self.queues[view].put_nowait(image))

    def read(self, snapshot) -> dict:
        if self.closed or self.count >= self.expected_frames:
            raise ValueError('original camera recorder closed or complete')
        frame = snapshot.frame
        pending = {}
        for view in VIEWS:
            try:
                image = self.queues[view].get(timeout=self.timeout_s)
            except Empty as exc:
                raise ValueError('original camera callback missing: ' + view) from exc
            width, height = self.profile[view]
            if image.frame != frame or image.width != width or image.height != height:
                raise ValueError('original camera frame or dimensions differ: ' + view)
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError('original camera BGRA buffer differs: ' + view)
            output = io.BytesIO()
            Image.frombytes('RGBA', (width, height), raw, 'raw', 'BGRA').convert('RGB').save(
                output, format='PNG')
            pending[view] = output.getvalue()
        for view, image_bytes in pending.items():
            (self.scratch / view / f'{self.count:06d}.png').write_bytes(image_bytes)
        self.count += 1
        return {view: frame for view in VIEWS}

    def finish(self, output: Path) -> dict:
        """Encode four lossless 20 Hz originals; return attempt-relative seals."""
        if self.closed or self.count != self.expected_frames:
            raise ValueError('complete original camera callbacks required')
        output = Path(output)
        if not output.is_dir() or any((output / f'{view}.mkv').exists() for view in VIEWS):
            raise ValueError('fresh original camera output required')
        refs = {}
        created = []
        try:
            for view in VIEWS:
                path = output / f'{view}.mkv'
                result = subprocess.run(
                    ['ffmpeg', '-v', 'error', '-xerror', '-framerate', '20',
                     '-i', str(self.scratch / view / '%06d.png'),
                     '-frames:v', str(self.expected_frames), '-c:v', 'ffv1',
                     '-level', '3', str(path)], capture_output=True, text=True)
                if result.returncode or not path.is_file() or path.stat().st_size == 0:
                    raise ValueError('original camera lossless encode failed: ' + view + ' ' + result.stderr[-200:])
                created.append(path)
                refs[view] = {'path': path.name,
                              'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}
            return refs
        except Exception:
            for path in created:
                path.unlink(missing_ok=True)
            raise

    def close(self) -> None:
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()

